fn price(order: &Order, qty: u32) -> f64 {
    struct Calc<'a> { order: &'a Order, qty: u32, subtotal: f64 }
    impl Calc<'_> {
        fn apply_discount(&mut self) { if self.qty > 100 { self.subtotal *= 0.95; } }
        fn compute(&mut self) -> f64 { self.apply_discount(); self.subtotal }
    }
    let mut c = Calc { order, qty, subtotal: order.base() * qty as f64 };
    c.compute()
}
